{"intent":"generate temp current-province to legacy-district mapping","expect":"Counts for 34 provinces and examples for HCM/Hanoi","script":"python3 - <<'PY'
import json, urllib.request, concurrent.futures, time
from collections import defaultdict
base='https://provinces.open-api.vn/api'
def get(url):
    with urllib.request.urlopen(url, timeout=25) as r: return json.load(r)
v1=get(base+'/v1/?depth=2')
v2=get(base+'/v2/?depth=2')
legacy_prov={p['code']:p for p in v1}
legacy_dist={d['code']:d for p in v1 for d in p['districts']}
wards=[(p['code'],p['name'],w['code']) for p in v2 for w in p.get('wards',[])]
print('v2 provinces', len(v2), 'wards', len(wards), 'v1 districts', len(legacy_dist))

def fetch(item):
    pcode,pname,wcode=item
    try:
        data=get(f'{base}/v2/w/{wcode}/to-legacies/')
        return pcode, data
    except Exception as e:
        return pcode, []
areas=defaultdict(set)
with concurrent.futures.ThreadPoolExecutor(max_workers=24) as ex:
    for idx,(pcode, data) in enumerate(ex.map(fetch, wards),1):
        for lw in data:
            dc=lw.get('district_code')
            if dc in legacy_dist: areas[pcode].add(dc)
        if idx%500==0: print('done', idx)
print('done all')
for p in v2:
    ds=sorted(areas[p['code']])
    print(p['code'], p['name'], len(ds))
    if p['name'] in ['Thành phố Hồ Chí Minh','Thành phố Hà Nội']:
        print([legacy_dist[d]['name']+'|'+legacy_prov[legacy_dist[d]['province_code']]['name'] for d in ds[:80]])
print('total unique assignments', sum(len(v) for v in areas.values()))
